(4541737, 653486, 56539, '<td valign="top">It would help if your photo had more "punch" to it</td>', 'It would help if your photo had more "punch" to it', '2008-03-05 19:49:56.000000', NULL, 1),
(4541741, 653786, 90658, '<td valign="top">Was this "tilt" natural in nature?  It seems as if this was a straight on shot of something that had an angle.  Nice shot, though, but not really "designed or showing motion."</td>', 'Was this "tilt" natural in nature?  It seems as if this was a straight on shot of something that had an angle.  Nice shot, though, but not really "designed or showing motion."', '2008-03-05 19:50:49.000000', NULL, 1),
