(4544556, 653486, 91118, '<td valign="top">This photo is extremely engaging. Well done.</td>', 'This photo is extremely engaging. Well done.', '2008-03-07 01:47:44.000000', NULL, 1),
(4544574, 654429, 26001, '<td valign="top">nice silhouette and excellent use of shadows.</td>', 'nice silhouette and excellent use of shadows.', '2008-03-07 02:40:51.000000', NULL, 1),
