(4548241, 654234, 91168, '<td valign="top"><b>I like this. It could be so much better if it was a bit clearer and sharper and the colours were more standing out. I like this, but it could look better in my opinion.</b></td>', 'I like this. It could be so much better if it was a bit clearer and sharper and the colours were more standing out. I like this, but it could look better in my opinion.', '2008-03-08 12:26:38.000000', NULL, 1),
(4548243, 654427, 91168, '<td valign="top"><b>This is very pretty. Clear and bright. Lighting - Great. Nice photo. Good luck. :]</b></td>', 'This is very pretty. Clear and bright. Lighting - Great. Nice photo. Good luck. :]', '2008-03-08 12:27:43.000000', NULL, 1),
(4548245, 654404, 91168, '<td valign="top"><b>The shiney door-knob is a great effect on this photo and draws you in. Nice work.</b></td>', 'The shiney door-knob is a great effect on this photo and draws you in. Nice work.', '2008-03-08 12:28:21.000000', NULL, 1),
(4548250, 654662, 88054, '<td valign="top">I''m hoping he is a base jumper. Would have liked a little tighter crop on the falling man but other than that...I really like it.</td>', 'I''m hoping he is a base jumper. Would have liked a little tighter crop on the falling man but other than that...I really like it.', '2008-03-08 12:30:19.000000', NULL, 1),
